'use client'

import * as React from 'react'
import { Collapsible, Slot, Tooltip } from 'radix-ui'
import { NavArrowRight } from 'iconoir-react'
import { cn } from '@/lib/utils'

/**
 * Sidebar, 1:1 with the uiKit sidebar sets: `sidebar/navigation` (0:3358), `sidebar/groupHeader`
 * (3468:18403) and `sidebar/subItem` (3468:18360).
 *
 * - `SidebarItem` is a 32px link row: 14px icon, medium 13/16 label in text/muted, radius-lg,
 *   8px padding. Hover fills bg/muted; the current page fills border/input and turns the label
 *   and icon text/default. `count` adds a red 16px counter; `iconOnly` is the 32 × 32 rail with
 *   the label in a tooltip.
 * - `SidebarGroup` is a collapsible group: the header row (12px padding, icon, label in
 *   text/default, a plain count, chevron right → down) and its `SidebarSubItem`s.
 * - `SidebarSubItem` is a regular 13px row whose text starts in line with the group label
 *   (34px in). Hover bg/muted, active bg/selected, disabled 50%.
 * - `SidebarSubGroup` is a sub-item that holds sub-items of its own (Chart → Bar chart,
 *   Channel chart): the same row with a chevron on the right, folding open and shut like the
 *   group (satin-expand, the chevron turning right → down). Its sub-items start 12px further
 *   in (46px). It opens on its own when one of them is the current page, and its label turns
 *   text/default while it holds the current page.
 *
 * Rows sit 2px apart. Focus draws the 1px border/focus outline Figma shows on the focus
 * variants, inset so the row doesn't move. Every state also answers to `data-force`.
 */

const rowFocus =
  'sa:outline-none sa:satin-focus:[box-shadow:inset_0_0_0_1px_var(--border-focus)]'

export interface SidebarProps extends React.ComponentProps<'nav'> {}

/** The navigation landmark. Name it with `aria-label` when a page has more than one nav. */
export function Sidebar({ className, ...props }: SidebarProps) {
  return <nav data-slot="sidebar" className={cn('sa:flex sa:flex-col sa:gap-0.5', className)} {...props} />
}

export interface SidebarItemProps extends Omit<React.ComponentProps<'a'>, 'children'> {
  label: string
  icon?: React.ReactNode
  /** The current page. Sets `aria-current="page"`. */
  active?: boolean
  /** Unread or pending work. Hidden at 0. */
  count?: number
  /** The collapsed rail: icon only, label in a tooltip. */
  iconOnly?: boolean
  disabled?: boolean
  /** Render your router's link instead of `<a>`. */
  asChild?: boolean
  children?: React.ReactNode
}

export function SidebarItem({
  className,
  label,
  icon,
  active = false,
  count,
  iconOnly = false,
  disabled = false,
  asChild = false,
  href,
  children,
  ...props
}: SidebarItemProps) {
  const Comp = asChild ? Slot.Root : 'a'
  const showCount = typeof count === 'number' && count > 0

  const row = (
    <Comp
      data-slot="sidebar-item"
      data-active={active || undefined}
      aria-current={active ? 'page' : undefined}
      aria-disabled={disabled || undefined}
      aria-label={iconOnly ? (showCount ? `${label}, ${count}` : label) : undefined}
      href={disabled ? undefined : href}
      tabIndex={disabled ? -1 : undefined}
      className={cn(
        'sa:flex sa:h-8 sa:shrink-0 sa:items-center sa:gap-2 sa:rounded-lg sa:px-2 sa:text-sm sa:leading-4 sa:font-medium sa:tracking-normal sa:text-text-muted sa:no-underline sa:select-none',
        'sa:transition-[background-color,color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
        'sa:[&_svg]:size-icon-size-sm sa:[&_svg]:shrink-0 sa:[&_svg]:[stroke-width:1.875]',
        'sa:not-data-active:satin-hover:bg-bg-muted',
        rowFocus,
        'sa:data-active:bg-border-input sa:data-active:text-text-default',
        'sa:aria-disabled:pointer-events-none sa:aria-disabled:opacity-50',
        iconOnly && 'sa:relative sa:size-8 sa:justify-center sa:px-0',
        className,
      )}
      {...props}
    >
      {asChild ? (
        children
      ) : (
        <>
          {icon}
          {!iconOnly && <span className="sa:min-w-0 sa:flex-1 sa:truncate">{label}</span>}
          {showCount && !iconOnly && <SidebarCount count={count} />}
          {showCount && iconOnly && (
            <span aria-hidden className="sa:absolute sa:top-1 sa:right-1 sa:size-1.5 sa:rounded-full sa:bg-action-destructive-bg" />
          )}
        </>
      )}
    </Comp>
  )

  if (!iconOnly) return row
  return (
    <Tooltip.Provider delayDuration={300}>
      <Tooltip.Root>
        <Tooltip.Trigger asChild>{row}</Tooltip.Trigger>
        <Tooltip.Portal>
          <Tooltip.Content
            side="right"
            sideOffset={6}
            collisionPadding={8}
            className="sa:z-50 sa:rounded-md sa:bg-action-inverse-bg sa:px-2 sa:py-1 sa:text-xs sa:font-medium sa:text-text-on-inverse sa:[box-shadow:0_1px_2px_0_var(--effect-shadow-xs)]"
          >
            {label}
          </Tooltip.Content>
        </Tooltip.Portal>
      </Tooltip.Root>
    </Tooltip.Provider>
  )
}

/** The red counter from sidebar/navigation: 16 high, 18 wide at least, radius-xs. */
function SidebarCount({ count }: { count: number }) {
  return (
    // 11/12 has no type token in the kit; Figma uses it raw for this counter.
    <span className="sa:inline-flex sa:h-4 sa:min-w-[18px] sa:shrink-0 sa:items-center sa:justify-center sa:rounded-xs sa:bg-action-destructive-bg sa:px-1 sa:text-[11px] sa:leading-3 sa:font-medium sa:tracking-normal sa:text-text-on-solid sa:tabular-nums">
      {count > 99 ? '99+' : count}
    </span>
  )
}

export interface SidebarGroupProps
  extends Omit<React.ComponentProps<typeof Collapsible.Root>, 'children'> {
  label: string
  icon?: React.ReactNode
  /** How many items the group holds. */
  count?: number
  children?: React.ReactNode
  /** Forwarded to the header button, e.g. `data-force="hover"` on a state sheet. */
  triggerProps?: React.ComponentProps<'button'> & { 'data-force'?: string }
}

export function SidebarGroup({
  className,
  label,
  icon,
  count,
  defaultOpen = true,
  open: openProp,
  onOpenChange,
  children,
  triggerProps,
  ...props
}: SidebarGroupProps) {
  // The group keeps its own open state and region, not Radix's Content: Content measures itself
  // with transitions switched off on every toggle, which would cut the fold (satin-expand).
  const [uncontrolled, setUncontrolled] = React.useState(defaultOpen)
  const open = openProp ?? uncontrolled
  const regionId = React.useId()
  return (
    <Collapsible.Root
      data-slot="sidebar-group"
      open={open}
      onOpenChange={(next) => {
        if (openProp == null) setUncontrolled(next)
        onOpenChange?.(next)
      }}
      className={cn('sa:group/sidebar-group sa:flex sa:flex-col sa:gap-0.5', className)}
      {...props}
    >
      <Collapsible.Trigger
        aria-controls={regionId}
        {...triggerProps}
        className={cn(
          'sa:flex sa:h-8 sa:w-full sa:shrink-0 sa:items-center sa:gap-2 sa:rounded-lg sa:px-3 sa:text-left sa:text-text-muted',
          'sa:transition-[background-color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
          'sa:[&_svg]:size-icon-size-sm sa:[&_svg]:shrink-0 sa:[&_svg]:[stroke-width:1.875]',
          'sa:not-data-active:satin-hover:bg-bg-muted',
          rowFocus,
          triggerProps?.className,
        )}
      >
        {icon}
        <span className="sa:min-w-0 sa:flex-1 sa:truncate sa:text-sm sa:leading-4 sa:font-medium sa:tracking-normal sa:text-text-default">
          {label}
        </span>
        {typeof count === 'number' && (
          <span className="sa:shrink-0 sa:px-1.5 sa:py-0.5 sa:text-sm sa:leading-4 sa:font-medium sa:tracking-normal sa:text-tone-fg sa:tabular-nums">
            {count}
          </span>
        )}
        <NavArrowRight
          aria-hidden
          className="sa:transition-transform sa:duration-(--sa-duration-base) sa:ease-(--sa-ease-out) sa:group-data-[state=open]/sidebar-group:rotate-90 sa:motion-reduce:transition-none"
        />
      </Collapsible.Trigger>
      {/* Always mounted so it can fold away: grows downwards from under the header (motion.css). */}
      <div id={regionId} data-state={open ? 'open' : 'closed'} className="satin-expand">
        <div className="sa:flex sa:flex-col sa:gap-0.5">{children}</div>
      </div>
    </Collapsible.Root>
  )
}

export interface SidebarSubItemProps extends Omit<React.ComponentProps<'a'>, 'children'> {
  label: string
  active?: boolean
  disabled?: boolean
  asChild?: boolean
  children?: React.ReactNode
}

export function SidebarSubItem({
  className,
  label,
  active = false,
  disabled = false,
  asChild = false,
  href,
  children,
  ...props
}: SidebarSubItemProps) {
  const Comp = asChild ? Slot.Root : 'a'
  return (
    <Comp
      data-slot="sidebar-sub-item"
      data-active={active || undefined}
      aria-current={active ? 'page' : undefined}
      aria-disabled={disabled || undefined}
      href={disabled ? undefined : href}
      tabIndex={disabled ? -1 : undefined}
      className={cn(
        'sa:flex sa:h-8 sa:shrink-0 sa:items-center sa:rounded-lg sa:pr-3 sa:pl-[34px] sa:text-sm sa:font-normal sa:text-text-muted sa:no-underline sa:select-none',
        'sa:transition-[background-color,color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
        'sa:not-data-active:satin-hover:bg-bg-muted sa:not-data-active:satin-hover:text-text-default',
        rowFocus,
        'sa:data-active:bg-bg-selected sa:data-active:text-text-default',
        'sa:aria-disabled:pointer-events-none sa:aria-disabled:opacity-50',
        className,
      )}
      {...props}
    >
      {asChild ? children : <span className="sa:min-w-0 sa:flex-1 sa:truncate">{label}</span>}
    </Comp>
  )
}

export interface SidebarSubGroupProps extends Omit<React.ComponentProps<'div'>, 'children'> {
  label: string
  /** Its `SidebarSubItem`s; they sit 12px further in. */
  children?: React.ReactNode
  /** One of its sub-items is the current page: opens it by default and marks the label. */
  active?: boolean
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
}

export function SidebarSubGroup({
  className,
  label,
  children,
  active = false,
  open: openProp,
  defaultOpen,
  onOpenChange,
  ...props
}: SidebarSubGroupProps) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultOpen ?? active)
  const open = openProp ?? uncontrolled
  const regionId = React.useId()
  return (
    <div data-slot="sidebar-sub-group" data-state={open ? 'open' : 'closed'} className={cn('sa:group/sub-group sa:flex sa:flex-col sa:gap-0.5', className)} {...props}>
      <button
        type="button"
        aria-expanded={open}
        aria-controls={regionId}
        data-active={active || undefined}
        onClick={() => {
          if (openProp == null) setUncontrolled(!open)
          onOpenChange?.(!open)
        }}
        className={cn(
          'sa:flex sa:h-8 sa:w-full sa:shrink-0 sa:items-center sa:gap-2 sa:rounded-lg sa:pr-3 sa:pl-[34px] sa:text-left sa:text-sm sa:font-normal sa:text-text-muted sa:select-none',
          'sa:transition-[background-color,color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
          'sa:satin-hover:bg-bg-muted sa:satin-hover:text-text-default sa:data-active:text-text-default',
          'sa:[&_svg]:size-icon-size-sm sa:[&_svg]:shrink-0 sa:[&_svg]:[stroke-width:1.875]',
          rowFocus,
        )}
      >
        <span className="sa:min-w-0 sa:flex-1 sa:truncate">{label}</span>
        <NavArrowRight
          aria-hidden
          className="sa:text-text-muted sa:transition-transform sa:duration-(--sa-duration-base) sa:ease-(--sa-ease-out) sa:group-data-[state=open]/sub-group:rotate-90 sa:motion-reduce:transition-none"
        />
      </button>
      <div id={regionId} data-state={open ? 'open' : 'closed'} className="satin-expand">
        <div className="sa:flex sa:flex-col sa:gap-0.5 sa:[&>[data-slot=sidebar-sub-item]]:pl-[46px]">{children}</div>
      </div>
    </div>
  )
}
